    static String s;
    static int n;

    // memo[state] = can this state avoid deadlock and eventually finish?
    // true  -> SAFE from this state
    // false -> UNSAFE from this state
    static Map<Long, Boolean> memo = new HashMap<>();
    static boolean[] inStack;

    static long encode(int[] pos, int[] owner) {
        long key = 0;

        // positions: base (n+1), 10 threads
        long mul = 1;
        for (int i = 0; i < 10; i++) {
            key += (long) pos[i] * mul;
            mul *= (n + 1L);
        }

        // owners: each lock owner in {-1,0..9} => store as 0..10, base 11
        for (int i = 0; i < 10; i++) {
            key += (long) (owner[i] + 1) * mul;
            mul *= 11L;
        }

        return key;
    }

    static boolean dfs(int[] pos, int[] owner) {
        long key = encode(pos, owner);
        Boolean got = memo.get(key);
        if (got != null) return got;

        boolean allDone = true;
        for (int i = 0; i < 10; i++) {
            if (pos[i] < n) {
                allDone = false;
                break;
            }
        }
        if (allDone) {
            memo.put(key, true);
            return true;
        }

        boolean hasMove = false;

        for (int t = 0; t < 10; t++) {
            if (pos[t] >= n) continue;

            char c = s.charAt(pos[t]);

            if (c == 'u') {
                // release the most recently acquired lock by this thread:
                // in this model, since the sequence is common to all threads and
                // releases correspond to previously acquired locks, the lock to
                // release is the latest lock owned by this thread in the prefix.
                // We can determine it by scanning the executed prefix of this thread.
                int lockToRelease = findLastHeldLock(t, pos[t], owner);
                if (lockToRelease != -1 && owner[lockToRelease] == t) {
                    hasMove = true;
                    int[] npos = pos.clone();
                    int[] nowner = owner.clone();
                    nowner[lockToRelease] = -1;
                    npos[t]++;
                    if (dfs(npos, nowner)) {
                        memo.put(key, true);
                        return true;
                    }
                }
            } else {
                int lock = c - '0';
                if (owner[lock] == -1 || owner[lock] == t) {
                    hasMove = true;
                    int[] npos = pos.clone();
                    int[] nowner = owner.clone();
                    nowner[lock] = t;
                    npos[t]++;
                    if (dfs(npos, nowner)) {
                        memo.put(key, true);
                        return true;
                    }
                }
            }
        }

        // If no thread can move and not all finished => deadlock
        // If every possible move leads to deadlock => unsafe
        memo.put(key, false);
        return false;
    }

    static int findLastHeldLock(int thread, int pos, int[] owner) {
        // Reconstruct stack-like lock behavior from the prefix of this thread.
        // Since only 10 locks exist, simple simulation is enough.
        boolean[] held = new boolean[10];
        int[] stack = new int[10];
        int top = 0;

        for (int i = 0; i < pos; i++) {
            char c = s.charAt(i);
            if (c == 'u') {
                if (top > 0) {
                    int lock = stack[--top];
                    held[lock] = false;
                }
            } else {
                int lock = c - '0';
                if (!held[lock]) {
                    held[lock] = true;
                    stack[top++] = lock;
                }
            }
        }

        if (top == 0) return -1;
        return stack[top - 1];
    }

    public static void main(String[] args) throws Exception {
