    int ownerMask;    // 2 bits per lock owner: 0 none, 1/2/3 thread id+1

    bool operator==(const State& other) const {
        return posMask == other.posMask && ownerMask == other.ownerMask;
    }
};

struct Hasher {
    size_t operator()(const State& s) const {
        return (uint64_t)s.posMask * 1000003ULL ^ (uint64_t)s.ownerMask;
    }
};

